#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <algorithm>
#include <climits>
using namespace std;

typedef long long ll;

const int MAXN = 210;
const int MAXM = 1000007;

char board1[15][15], board2[15][15];
int mapping[15][15], total_nodes;
int src, dst, time_limit, grid_size;
int zero_pos_x, zero_pos_y;
const int dr[4] = {0, 0, 1, -1};
const int dc[4] = {1, -1, 0, 0};

bool in_bounds(int r, int c) {
    return r >= 0 && c >= 0 && r < grid_size && c < grid_size && board1[r][c] >= '0' && board1[r][c] <= '9';
}

struct FlowEdge {
    int to, cap, rev_idx;
    FlowEdge(int t, int c, int r) : to(t), cap(c), rev_idx(r) {}
};

vector<FlowEdge> adj[MAXN * 2];
int level[MAXN], iter[MAXN];

void connect(int u, int v, int capacity) {
    adj[u].emplace_back(v, capacity, adj[v].size());
    adj[v].emplace_back(u, 0, adj[u].size() - 1);
}

void expand_from(int r, int c) {
    if (board2[r][c] != '\0') {
        connect(mapping[r][c] + total_nodes, dst, board2[r][c] - '0');
    }
    if (board1[r][c] == '0') return;

    connect(src, mapping[r][c], board1[r][c] - '0');
    if (board2[r][c] != '\0') {
        connect(mapping[r][c], mapping[r][c] + total_nodes, 10);
    }

    int start_r = r, start_c = c;
    queue<int> q1_r, q1_c;
    queue<int> q2_r, q2_c;
    q1_r.push(r); q1_c.push(c);
    q2_r.push(zero_pos_x); q2_c.push(zero_pos_y);

    vector<vector<int>> dist1(grid_size, vector<int>(grid_size, -1));
    vector<vector<int>> dist2(grid_size, vector<int>(grid_size, -1));
    dist1[r][c] = 0;
    dist2[zero_pos_x][zero_pos_y] = 0;

    while (!q1_r.empty()) {
        int sz = q1_r.size();
        for (int i = 0; i < sz; ++i) {
            int cur_r = q1_r.front(); q1_r.pop();
            int cur_c = q1_c.front(); q1_c.pop();
            if (dist2[cur_r][cur_c] >= 0) continue;
            for (int k = 0; k < 4; ++k) {
                int nr = cur_r + dr[k], nc = cur_c + dc[k];
                if (in_bounds(nr, nc) && dist1[nr][nc] == -1) {
                    dist1[nr][nc] = dist1[cur_r][cur_c] + 1;
                    if (dist1[nr][nc] > time_limit) break;
                    if (dist2[nr][nc] >= 0) continue;
                    q1_r.push(nr); q1_c.push(nc);
                    if (board2[nr][nc] != '0') {
                        connect(mapping[start_r][start_c], mapping[nr][nc] + total_nodes, 10);
                    }
                }
            }
        }

        sz = q2_r.size();
        for (int i = 0; i < sz; ++i) {
            int cur_r = q2_r.front(); q2_r.pop();
            int cur_c = q2_c.front(); q2_c.pop();
            for (int k = 0; k < 4; ++k) {
                int nr = cur_r + dr[k], nc = cur_c + dc[k];
                if (in_bounds(nr, nc) && dist2[nr][nc] == -1) {
                    dist2[nr][nc] = dist2[cur_r][cur_c] + 1;
                    q2_r.push(nr); q2_c.push(nc);
                }
            }
        }
    }
}

bool level_graph() {
    memset(level, -1, sizeof(level));
    queue<int> q;
    q.push(src);
    level[src] = 0;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (const auto& e : adj[u]) {
            if (e.cap > 0 && level[e.to] == -1) {
                level[e.to] = level[u] + 1;
                q.push(e.to);
            }
        }
    }
    return level[dst] != -1;
}

int blocking_flow(int u, int flow) {
    if (u == dst) return flow;
    for (int& i = iter[u]; i < adj[u].size(); ++i) {
        FlowEdge& e = adj[u][i];
        if (e.cap > 0 && level[e.to] == level[u] + 1) {
            int pushed = blocking_flow(e.to, min(flow, e.cap));
            if (pushed > 0) {
                e.cap -= pushed;
                adj[e.to][e.rev_idx].cap += pushed;
                return pushed;
            }
        }
    }
    return 0;
}

int dinic() {
    int total = 0;
    while (level_graph()) {
        memset(iter, 0, sizeof(iter));
        int pushed;
        while ((pushed = blocking_flow(src, INT_MAX)) > 0) {
            total += pushed;
        }
    }
    return total;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> grid_size >> time_limit;
    for (int i = 0; i < grid_size; ++i) cin >> board1[i];
    for (int i = 0; i < grid_size; ++i) cin >> board2[i];

    memset(mapping, -1, sizeof(mapping));
    total_nodes = 0;
    for (int i = 0; i < grid_size; ++i) {
        for (int j = 0; j < grid_size; ++j) {
            if (board1[i][j] == 'Z') {
                zero_pos_x = i; zero_pos_y = j;
            } else if (in_bounds(i, j)) {
                mapping[i][j] = ++total_nodes;
            }
        }
    }

    src = 0;
    dst = 2 * total_nodes + 1;

    for (int i = 0; i < grid_size; ++i) {
        for (int j = 0; j < grid_size; ++j) {
            if (in_bounds(i, j)) {
                expand_from(i, j);
            }
        }
    }

    cout << dinic() << '\n';
    return 0;
}
